      await userEvent.selectOptions(screen.getByLabelText("정렬"), "updated");
    }
    expect(await screen.findByRole("heading", { name: "Catalog App 1" })).toBeVisible();
    expect(screen.getByText("1 페이지")).toBeVisible();
    expect(screen.getByRole("button", { name: "목록", exact: true })).toHaveAttribute("aria-pressed", "true");
    expect(requests.at(-1)?.searchParams.get("offset")).toBe("0");
  });

